import { Component, OnInit } from '@angular/core';
import { UntypedFormBuilder, UntypedFormGroup, Validators } from '@angular/forms';
import { AuthenticationService } from 'src/app/shared/services/authentication.service';
import { NzNotificationService } from 'ng-zorro-antd/notification';

@Component({
  selector: 'app-forgot-password',
  templateUrl: './forgot-password.component.html',
  styleUrls: ['./forgot-password.component.css']
})
export class ForgotPasswordComponent implements OnInit {

  forgotForm: UntypedFormGroup;
  isSubmitting = false;
  isSent = false;
  sentTo = '';

  constructor(
    private fb: UntypedFormBuilder,
    private authenticationService: AuthenticationService,
    private notification: NzNotificationService
  ) {}

  ngOnInit(): void {
    this.forgotForm = this.fb.group({
      email: [null, [Validators.required, Validators.email]]
    });
  }

  submitForm(): void {
    for (const i in this.forgotForm.controls) {
      this.forgotForm.controls[i].markAsDirty();
      this.forgotForm.controls[i].updateValueAndValidity();
    }

    if (this.forgotForm.invalid) return;

    this.isSubmitting = true;

    const email = (this.forgotForm.value.email || '').trim();

    this.authenticationService.forgotPassword(email).subscribe({
      next: () => {
        // A 200 now means the account was found and the mail was handed to the
        // provider, so the confirmation can name the address.
        this.sentTo = email;
        this.isSent = true;
        this.isSubmitting = false;
      },
      error: (err) => {
        // 404 carries "No dashboard account is registered with this email
        // address" - surfaced as-is so an unregistered address is obvious.
        this.notification.error(
          'Error',
          err?.error?.message || 'Could not send the reset link. Please try again.'
        );
        this.isSubmitting = false;
      }
    });
  }
}
