import { Component, OnInit } from '@angular/core';
import { AbstractControl, UntypedFormBuilder, UntypedFormGroup, ValidationErrors, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { AuthenticationService } from 'src/app/shared/services/authentication.service';
import { NzNotificationService } from 'ng-zorro-antd/notification';

@Component({
  selector: 'app-reset-password',
  templateUrl: './reset-password.component.html',
  styleUrls: ['./reset-password.component.css']
})
export class ResetPasswordComponent implements OnInit {

  resetForm: UntypedFormGroup;
  isSubmitting = false;
  token: string | null = null;

  constructor(
    private fb: UntypedFormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private authenticationService: AuthenticationService,
    private notification: NzNotificationService
  ) {}

  ngOnInit(): void {
    this.token = this.route.snapshot.queryParamMap.get('token');

    this.resetForm = this.fb.group({
      newPassword: [null, [Validators.required, Validators.minLength(8)]],
      confirmPassword: [null, [Validators.required]]
    }, { validators: this.passwordsMatch });
  }

  passwordsMatch(group: AbstractControl): ValidationErrors | null {
    const newPassword = group.get('newPassword')?.value;
    const confirmPassword = group.get('confirmPassword')?.value;
    return newPassword && confirmPassword && newPassword !== confirmPassword
      ? { mismatch: true }
      : null;
  }

  submitForm(): void {
    for (const i in this.resetForm.controls) {
      this.resetForm.controls[i].markAsDirty();
      this.resetForm.controls[i].updateValueAndValidity();
    }

    if (this.resetForm.invalid || !this.token) return;

    this.isSubmitting = true;

    this.authenticationService.resetPassword(this.token, this.resetForm.value.newPassword).subscribe({
      next: () => {
        this.notification.success('Success', 'Your password has been reset. Please sign in.');
        this.router.navigate(['/authentication/login']);
      },
      error: (err) => {
        this.notification.error(
          'Error',
          err?.error?.message || 'This reset link is invalid or has expired.'
        );
        this.isSubmitting = false;
      }
    });
  }
}
